content.solution_code:
class Instrument {
  constructor(type) {
    this.type = type;
  }

  makeSound() {
    return "Generic instrument sound.";
  }
}

class Drum extends Instrument {
  constructor(type, material) {
    super(type);
    this.material = material;
  }

  makeSound() {
    return `Thump-thump! (a ${this.material} ${this.type} drum).`;
  }
}

const genericInstrument = new Instrument("Wind");
console.log(genericInstrument.makeSound());

const snareDrum = new Drum("Snare", "metal");
console.log(snareDrum.makeSound());
console.log(snareDrum instanceof Instrument);

